#!/usr/bin/env python3
"""Compare independent GNU and MiniAS production assembly *input* manifests.

An input manifest is generated by an assembler wrapper while the original
GCC-produced assembly is still available.  Its rows are target-object-relative
paths and SHA-256 digests of the exact assembly bytes sent to the assembler.

Accepted formats:

* JSONL: {"object":"arch/.../foo.o","assembly_sha256":"<64 hex>"}
* TSV:   object<TAB>assembly_sha256 header, then two columns per object

This checker proves identical input sets and bytes *only when both independently
produced manifests have been collected*. It does not prove ELF equivalence,
correctness, or MiniAS ownership; the production provenance and QEMU gates
remain independent requirements.
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path, PurePosixPath
import re
import sys


SHA256 = re.compile(r"[a-f0-9]{64}\Z")
MAX_MANIFEST_BYTES = 16 * 1024 * 1024
MAX_MANIFEST_ROWS = 100_000


class ManifestError(ValueError):
    """Fail-closed malformed input, incomplete evidence or cross-lane drift."""


def canonical_owner(owner: object, context: str) -> str:
    if not isinstance(owner, str) or not owner:
        raise ManifestError(f"{context}: missing object path")
    if (owner != owner.strip() or "\\" in owner or "\x00" in owner or
            "\n" in owner or "\r" in owner or "\t" in owner):
        raise ManifestError(f"{context}: invalid object path {owner!r}")
    path = PurePosixPath(owner)
    if (path.is_absolute() or path.as_posix() != owner or
            ".." in path.parts or path.suffix != ".o" or
            not path.name or owner.startswith("-")):
        raise ManifestError(f"{context}: noncanonical or escaping object path {owner!r}")
    return owner


def require_digest(value: object, context: str) -> str:
    if not isinstance(value, str) or SHA256.fullmatch(value) is None:
        raise ManifestError(f"{context}: missing or invalid assembly SHA-256")
    return value


def unique_json_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise ManifestError(f"duplicate JSON field {key!r}")
        result[key] = value
    return result


def read_manifest(path: Path) -> dict[str, str]:
    if not path.is_file() or path.is_symlink():
        raise ManifestError(f"manifest is absent, not regular, or symlinked: {path}")
    if path.stat().st_size > MAX_MANIFEST_BYTES:
        raise ManifestError(f"manifest exceeds {MAX_MANIFEST_BYTES} bytes: {path}")
    try:
        content = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise ManifestError(f"cannot read manifest {path}: {exc}") from exc
    lines = content.splitlines()
    if not lines:
        raise ManifestError(f"empty manifest: {path}")
    if len(lines) > MAX_MANIFEST_ROWS + 1:
        raise ManifestError(f"manifest has too many rows: {path}")

    if path.suffix == ".tsv":
        if lines[0] != "object\tassembly_sha256":
            raise ManifestError(f"invalid TSV schema header: {path}")
        items = lines[1:]
        if not items:
            raise ManifestError(f"TSV manifest has no objects: {path}")

        def parse(line: str, number: int) -> tuple[object, object]:
            fields = line.split("\t")
            if len(fields) != 2:
                raise ManifestError(f"{path}:{number}: expected exactly two TSV fields")
            return fields[0], fields[1]

        start_line = 2
    elif path.suffix == ".jsonl":
        items = lines

        def parse(line: str, number: int) -> tuple[object, object]:
            try:
                data = json.loads(line, object_pairs_hook=unique_json_object)
            except (json.JSONDecodeError, ManifestError) as exc:
                raise ManifestError(f"{path}:{number}: malformed JSONL: {exc}") from exc
            if not isinstance(data, dict) or set(data) != {"object", "assembly_sha256"}:
                raise ManifestError(f"{path}:{number}: invalid JSONL schema")
            return data["object"], data["assembly_sha256"]

        start_line = 1
    else:
        raise ManifestError(f"unsupported manifest suffix (use .tsv or .jsonl): {path}")

    owners: dict[str, str] = {}
    for number, line in enumerate(items, start_line):
        owner, digest = parse(line, number)
        rel = canonical_owner(owner, f"{path}:{number}")
        value = require_digest(digest, f"{path}:{number} object={rel}")
        if rel in owners:
            raise ManifestError(f"{path}:{number}: duplicate production owner {rel!r}")
        owners[rel] = value
    if not owners:
        raise ManifestError(f"manifest has no production objects: {path}")
    return owners


def compare(mini: dict[str, str], gnu: dict[str, str], min_objects: int) -> int:
    if min_objects < 1:
        raise ManifestError("--min-objects must be at least 1")
    if len(mini) < min_objects or len(gnu) < min_objects:
        raise ManifestError(
            f"too few objects: minias={len(mini)} gnu={len(gnu)} "
            f"required={min_objects}")
    mini_only = sorted(mini.keys() - gnu.keys())
    gnu_only = sorted(gnu.keys() - mini.keys())
    if mini_only or gnu_only:
        raise ManifestError(
            "production object set mismatch "
            f"minias_only={len(mini_only)} examples={mini_only[:8]} "
            f"gnu_only={len(gnu_only)} examples={gnu_only[:8]}")
    mismatched = sorted(owner for owner in mini if mini[owner] != gnu[owner])
    if mismatched:
        raise ManifestError(
            f"GNU/MiniAS GCC assembly input SHA mismatch objects={len(mismatched)} "
            f"examples={mismatched[:8]}")
    return len(mini)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--mini-manifest", required=True, type=Path)
    parser.add_argument("--gnu-manifest", required=True, type=Path)
    parser.add_argument("--min-objects", type=int, default=1)
    parser.add_argument("--arch", required=True)
    args = parser.parse_args(argv)
    try:
        mini = read_manifest(args.mini_manifest)
        gnu = read_manifest(args.gnu_manifest)
        checked = compare(mini, gnu, args.min_objects)
    except (ManifestError, OSError) as exc:
        print(f"MINIAS_LINUX_ALL_ASM_SOURCES_FAIL arch={args.arch} "
              f"reason={exc}", file=sys.stderr)
        return 1
    print(f"MINIAS_LINUX_ALL_ASM_SOURCES_PASS arch={args.arch} "
          f"objects={checked} exact_owner_set=1 exact_sha256=1 "
          "independent_gnu_control=required gnu_elf_equivalence=NOT_CERTIFIED")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
